(() => {
const $=s=>document.querySelector(s), all=s=>Array.from(document.querySelectorAll(s));
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>Number(n).toLocaleString('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0});
const initials=n=>n.split(' ').map(p=>p[0]).slice(0,2).join('');
const today='2026-11-23';
let products=structuredClone(seedProducts),deals=structuredClone(seedDeals),stages=['Entrada','Qualificação','Reunião','Proposta'];
let pipelines=[{name:'Novos negócios',stages:[...stages]}],pipeline='Novos negócios';
let section=location.hash.slice(1)||'funis',profile='manager';
let rules=[{field:'status',op:'eq',value:'Aberta'}],logic='all',draftRules=[],draftLogic='all',search='';
let tasks=deals.filter(d=>d.status==='Aberta').map((d,i)=>({id:'DEMO-'+(101+i),deal:d.id,title:d.activity,owner:d.owner,due:d.due,status:'Pendente',source:'ClickUp'}));
let taskOwner='Todos',taskDue='Todos',taskDate='',taskSearch='',catalogSearch='',sdrScope='Todos',selectedSDR='CorpLaw';
let savedDashboards=[{id:'dash1',name:'Insights Radar · exemplo',rules:[{field:'status',op:'eq',value:'Aberta'}],logic:'all',metric:'value',group:'stage'}],activeDash='dash1';
let meetingDraft=null,meetingError=false,detailId=null,activityLog=[],taskOnly=false;
const fieldDefs={stage:{label:'Etapa',values:()=>stages},status:{label:'Situação',values:()=>['Aberta','Ganha','Perdida']},owner:{label:'Responsável',values:()=>['Saulo Alves','Gustavo Costa']},origin:{label:'Origem',values:()=>['Raio X','Indicação','Site']},rx:{label:'Raio X concluído · personalizado',values:()=>['Sim','Não']},meeting:{label:'Reunião marcada · personalizado',values:()=>['Sim','Não']},priority:{label:'Prioridade · personalizado',values:()=>['Alta','Normal']},product:{label:'Produto vinculado',values:()=>['Ausente',...products.map(p=>p.name)]},company:{label:'Nome da oportunidade',values:null}};
function valueOf(d,key){if(['rx','meeting'].includes(key))return d[key]?'Sim':'Não';if(key==='product')return products.find(p=>p.id===d.product)?.name||'Ausente';return d[key];}
function matches(d,r){const val=String(valueOf(d,r.field)).toLowerCase(),want=String(r.value).toLowerCase();return r.op==='neq'?val!==want:r.op==='contains'?val.includes(want):val===want;}
function filtered(rs=rules,l=logic){return deals.filter(d=>d.pipeline?d.pipeline===pipeline:pipeline==='Novos negócios').filter(d=>!rs.length||(l==='all'?rs.every(r=>matches(d,r)):rs.some(r=>matches(d,r)))).filter(d=>!search||[d.company,d.contact,d.email].join(' ').toLowerCase().includes(search.toLowerCase()));}
function tag(t,color=''){return `<span class="tag ${color}">${esc(t)}</span>`;}
function owner(n){return `<span class="avatar" title="${esc(n)}">${initials(n)}</span>`;}
function productLabel(d){const p=products.find(p=>p.id===d.product);return p?`<span>${esc(p.name)}</span>`:tag('Produto não vinculado','amber');}
const sections=new Set(['funis','atividades','catalogo','sdr','segmentos','ajustes','insights']);
section=sections.has(section)?section:'funis';
function nav(next){section=sections.has(next)?next:'funis';if(location.hash!=='#'+section)history.pushState(null,'','#'+section);render();$('#main').focus({preventScroll:true});window.scrollTo(0,0);}
window.addEventListener('hashchange',()=>{if(location.hash==='#main')return;section=sections.has(location.hash.slice(1))?location.hash.slice(1):'funis';close();render();$('#main').focus({preventScroll:true});});
$('.skip').addEventListener('click',event=>{event.preventDefault();$('#main').focus();});
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
let dialogOrigin=null;
function restoreDialogFocus(){
  if($('#dialog').open)return;
  const origin=dialogOrigin;
  const replacement=origin?.id?document.getElementById(origin.id):origin?.dataset.open?all('[data-open]').find(el=>el.dataset.open===origin.dataset.open):origin?.dataset.task?all('[data-task]').find(el=>el.dataset.task===origin.dataset.task):null;
  (origin?.isConnected?origin:replacement||$('#main'))?.focus({preventScroll:true});
}
$('#dialog').addEventListener('close',restoreDialogFocus);
$('#dialog').addEventListener('keydown', event => {
  if (event.key !== 'Tab') return;
  const controls = [...event.currentTarget.querySelectorAll('button, a[href], input, select, textarea, [tabindex]')]
    .filter(el => el.tabIndex >= 0 && !el.matches(':disabled') && el.getClientRects().length);
  if (!controls.length) return;
  const first = controls[0], last = controls.at(-1);
  const wrap = event.shiftKey
    ? document.activeElement === first || !controls.includes(document.activeElement)
    : document.activeElement === last;
  if (wrap) {
    event.preventDefault();
    (event.shiftKey ? last : first).focus();
  }
});
function close(){if($('#dialog').open)$('#dialog').close();}
function modal(title,html,kind='',sub='Demonstração · dados fictícios'){
  const dialog=$('#dialog');
  if(!dialog.open)dialogOrigin=document.activeElement;
  dialog.className=kind;
  dialog.innerHTML=`<header class="dialog-head"><div><h2 id="dialog-title" tabindex="-1">${title}</h2><p>${sub}</p></div><button class="close" aria-label="Fechar" data-close>×</button></header><div class="dialog-body">${html}</div>`;
  if(!dialog.open)dialog.showModal();
  dialog.scrollTop=0;
  $('#dialog-title').focus({preventScroll:true});
  dialog.querySelector('[data-close]').onclick=close;
}
function shell(){return `<aside class="sidebar"><img class="logo" src="assets/logo.png" alt="CorpLaw"><p class="side-label">PAINEL CORPLAW</p><span class="side-item"><span class="side-icon">⌂</span>Dashboard</span><a class="side-item active" href="#funis" data-nav="funis"><span class="side-icon">↗</span>Comercial</a><span class="side-item"><span class="side-icon">♧</span>Clientes</span><span class="side-item"><span class="side-icon">⊙</span>Navegador</span><span class="side-item"><span class="side-icon">▦</span>Usuários</span><div class="side-foot"><span class="muted">Identidade do painel existente.<br>Demais módulos fora desta proposta.</span><div class="profile">${owner('Gustavo Costa')}<div><strong>Gustavo Costa</strong><br><span class="muted">Identidade individual · exemplo</span></div></div></div></aside><div class="shell"><header class="topbar"><img class="mobile-logo" src="assets/logo.png" alt="CorpLaw"><div class="crumb">Painel CorpLaw <strong>/ Comercial</strong></div><div class="role"><span class="muted">Simular acesso</span><select id="profile" aria-label="Perfil de acesso simulado"><option value="manager" ${profile==='manager'?'selected':''}>Gestão comercial · hipótese</option><option value="reader" ${profile==='reader'?'selected':''}>Comercial · hipótese</option></select>${owner('Gustavo Costa')}</div></header><div class="demo"><span><strong>PROTÓTIPO · DADOS FICTÍCIOS</strong> · 23/11/2026 · Nenhuma integração ativa</span><a href="#ajustes" data-nav="ajustes">Decisões e validações ↗</a></div><main class="workspace" id="main" tabindex="-1"><div class="pagehead"><div><p class="eyebrow">Área comercial</p><h1>${section==='insights'?'Insights comerciais':'Relacionamentos que avançam'}</h1><p class="subtitle">${section==='insights'?'Filtros viram leituras compartilhadas, sem perder o contexto.':'Da primeira conversa à próxima decisão, no mesmo painel.'}</p></div><span class="tag teal">Proposta para validação</span></div><nav class="tabs major" aria-label="Subáreas de Comercial"><button data-nav="funis" aria-current="${section!=='insights'?'page':'false'}">CRM</button><button data-nav="insights" aria-current="${section==='insights'?'page':'false'}">Insights</button></nav>${section!=='insights'?`<nav class="tabs" aria-label="Áreas do CRM">${[['funis','Funis'],['atividades','Atividades'],['catalogo','Catálogo'],['sdr','Gestão de SDR'],['segmentos','Segmentos'],['ajustes','Configuração do CRM']].map(([s,t])=>`<button data-nav="${s}" aria-current="${section===s?'page':'false'}">${t}</button>`).join('')}</nav>`:''}<div id="content">${({funis:board,atividades:activities,catalogo:catalog,sdr:sdr,segmentos:segments,ajustes:settings,insights:insights}[section]||board)()}</div><p class="foot">Design isolado · funis, campos e permissões são hipóteses a validar com Saulo e Gustavo. <a href="#ajustes" data-nav="ajustes">Ver escopo e referências</a></p></main></div>`;}
function filterChips(rs=rules,l=logic){return `<div class="filterline"><span>${l==='all'?'Todas as condições (E)':'Qualquer condição (OU)'}</span>${rs.map(r=>`<span class="filterchip">${esc(fieldDefs[r.field].label.split(' · ')[0])} ${r.op==='neq'?'≠':r.op==='contains'?'contém':'='} ${esc(r.value)}</span>`).join('')}${!rs.length?'<span>Sem restrições</span>':''}</div>`;}
function card(d){return `<article class="deal" draggable="${profile==='manager'}" data-drag="${d.id}"><button class="open-deal" data-open="${d.id}"><strong class="deal-name">${esc(d.company)}</strong><span class="deal-contact">${esc(d.contact)}</span>${tag(d.origin,d.origin==='Raio X'?'teal':'')}<p class="deal-value">${money(d.value)}</p><div class="deal-product">${productLabel(d)}</div></button><div class="deal-bottom"><div class="due ${d.due<today?'overdue':''}">${d.due<today?'◷ Atrasada':'◷ '+(d.due===today?'Hoje':'24–25 nov')}<br>${esc(d.activity)}</div>${owner(d.owner)}</div></article>`;}
function board(){const rows=filtered();return `<div class="toolbar"><label class="field">Funil<select id="pipeline">${pipelines.map(p=>`<option ${pipeline===p.name?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><input type="search" id="deal-search" placeholder="Buscar oportunidade ou contato" aria-label="Buscar oportunidade ou contato" value="${esc(search)}"><button class="btn" data-filters>≡ Filtros <span class="tabcount">${rules.length}</span></button><button class="btn manager-only" data-save-insights>Salvar em Insights ↗</button><button class="btn primary manager-only spacer" data-config-funnel>Configurar funil</button></div>${filterChips()}<div class="board-summary"><span><strong>${rows.length} oportunidades</strong> · ${money(rows.reduce((s,d)=>s+d.value,0))} no recorte</span><span class="muted">${rows.filter(d=>!d.product).length} sem produto vinculado</span></div>${!rows.length?`<div class="empty"><h2>Nenhuma oportunidade neste recorte</h2><p>Os filtros continuam ativos. Ajuste as condições ou crie as etapas de um novo funil.</p><button class="btn" data-filters>Rever filtros</button></div>`:`<div class="board" style="--lane-count:${stages.length}">${stages.map(s=>{const list=rows.filter(d=>d.stage===s);return `<section class="lane" data-lane="${esc(s)}" aria-label="Etapa ${esc(s)}"><header class="lane-head"><div class="lane-title"><i></i><b>${esc(s)}</b><span class="tabcount">${list.length}</span></div><p>${money(list.reduce((sum,d)=>sum+d.value,0))}</p></header>${list.map(card).join('')}${!list.length?'<p class="muted" style="font-size:11px;padding:12px">Sem oportunidades nesta etapa.</p>':''}</section>`;}).join('')}</div>`}<p class="board-tip">Abra um cartão para ver contato, produto e atividades. Mova pela ficha ou arraste entre etapas no desktop. Ganho e perdido são situações independentes da etapa.</p>`;}
function filterValue(r,i){const opts=fieldDefs[r.field].values?.();return opts?`<select data-rule-value="${i}">${opts.map(v=>`<option ${r.value===v?'selected':''}>${esc(v)}</option>`).join('')}</select>`:`<input data-rule-value="${i}" value="${esc(r.value)}" placeholder="Texto a encontrar">`;}
function filterDialog(reset=false){if(reset){draftRules=structuredClone(rules);draftLogic=logic;}modal('Combinar filtros',`<p class="muted">Refine as oportunidades por etapa, situação e campos personalizados. O resultado usa apenas os registros fictícios deste protótipo.</p><div class="toolbar"><label class="field">Combinação<select id="filter-logic"><option value="all" ${draftLogic==='all'?'selected':''}>Todas as condições · E</option><option value="any" ${draftLogic==='any'?'selected':''}>Qualquer condição · OU</option></select></label><span class="filter-preview">${filtered(draftRules,draftLogic).length}</span><span class="muted">oportunidades</span></div>${draftRules.map((r,i)=>`<div class="rule"><label class="field">Campo<select data-rule-field="${i}">${Object.entries(fieldDefs).map(([k,f])=>`<option value="${k}" ${r.field===k?'selected':''}>${f.label}</option>`).join('')}</select></label><label class="field">Condição<select data-rule-op="${i}"><option value="eq" ${r.op==='eq'?'selected':''}>É igual a</option><option value="neq" ${r.op==='neq'?'selected':''}>É diferente de</option><option value="contains" ${r.op==='contains'?'selected':''}>Contém</option></select></label><label class="field">Valor${filterValue(r,i)}</label><button class="btn" data-remove-rule="${i}" aria-label="Remover condição ${i+1}">×</button></div>`).join('')}<button class="btn link" id="add-rule">+ Adicionar condição</button><div class="notice"><strong>Exemplo: Raio X concluído + reunião não marcada</strong>Combine campos personalizados com etapa e situação. Salve o recorte em Insights depois de aplicá-lo.</div><div class="dialog-footer"><button class="btn" id="reset-filter">Limpar</button><button class="btn primary" id="apply-filter">Aplicar filtros</button></div>`,'wide');$('#filter-logic').onchange=e=>{draftLogic=e.target.value;filterDialog();};all('[data-rule-field]').forEach(el=>el.onchange=e=>{const r=draftRules[Number(el.dataset.ruleField)];r.field=e.target.value;r.value=fieldDefs[r.field].values?.()[0]||'';filterDialog();});all('[data-rule-op]').forEach(el=>el.onchange=e=>{draftRules[Number(el.dataset.ruleOp)].op=e.target.value;filterDialog();});all('[data-rule-value]').forEach(el=>el.onchange=e=>{draftRules[Number(el.dataset.ruleValue)].value=e.target.value;filterDialog();});all('[data-remove-rule]').forEach(el=>el.onclick=()=>{draftRules.splice(Number(el.dataset.removeRule),1);filterDialog();});$('#add-rule').onclick=()=>{draftRules.push({field:'origin',op:'eq',value:'Raio X'});filterDialog();};$('#reset-filter').onclick=()=>{draftRules=[];draftLogic='all';filterDialog();};$('#apply-filter').onclick=()=>{rules=structuredClone(draftRules);logic=draftLogic;close();render();toast('Recorte aplicado às oportunidades fictícias.');};}
function baseOpenDeal(id){detailId=id;const d=deals.find(d=>d.id===id),p=products.find(p=>p.id===d.product),related=tasks.filter(t=>t.deal===id);modal(esc(d.company),`${tag(d.status,d.status==='Ganha'?'green':d.status==='Perdida'?'red':'teal')} ${tag(d.stage)}<div class="detail-actions"><button class="btn primary manager-only" id="schedule">Agendar reunião</button><button class="btn" id="go-tasks">Ver atividades · ${related.length}</button><button class="btn manager-only" id="move-deal">Mover oportunidade</button></div><h3 class="section-title">Contato e origem</h3><dl class="definition"><div><dt>Contato</dt><dd>${esc(d.contact)}</dd></div><div><dt>E-mail do lead</dt><dd>${esc(d.email)}</dd></div><div><dt>Origem</dt><dd>${esc(d.origin)}</dd></div><div><dt>Responsável individual</dt><dd>${esc(d.owner)}</dd></div><div><dt>Valor da oportunidade</dt><dd>${money(d.value)}</dd></div><div><dt>Telefone · fictício</dt><dd>${esc(d.phone)}</dd></div></dl><h3 class="section-title">Produto e classificação</h3>${p?`<strong>${esc(p.name)}</strong><p class="muted" style="margin-top:5px">${esc(p.code)} · ${esc(p.category)}<br>Centro de custo: ${esc(p.center)}</p>`:`<div class="notice amber"><strong>Produto ausente nesta oportunidade</strong>A cobertura de produto no Supabase foi relatada como incompleta. Não presumimos classificação nem incluímos este valor em um centro de custo por conta própria.</div>`}<button class="btn link manager-only" id="link-product">${p?'Alterar produto do catálogo':'Vincular produto padronizado'} →</button><h3 class="section-title">Campos personalizados · proposta</h3><dl class="definition"><div><dt>Raio X concluído</dt><dd>${d.rx?'Sim':'Não'}</dd></div><div><dt>Reunião marcada</dt><dd>${d.meeting?'Sim':'Não'}</dd></div><div><dt>Prioridade</dt><dd>${esc(d.priority)}</dd></div><div><dt>SDR de origem</dt><dd>${esc(d.sdr)}</dd></div></dl><h3 class="section-title">Anotações</h3><p>${esc(d.note)}</p><h3 class="section-title">Próxima atividade</h3>${related.map(t=>`<button class="row-link" data-task="${t.id}">${esc(t.title)} ↗</button><p class="muted">${esc(t.owner)} · ${t.due} · ClickUp simulado</p>`).join('')||'<p class="muted">Sem atividades vinculadas.</p>'}<div class="timeline">${activityLog.filter(a=>a.deal===id).map(a=>`<article><strong>${esc(a.title)}</strong><small>Gustavo Costa · simulação local</small><p>${esc(a.body)}</p></article>`).join('')}</div>`,'drawer','Ficha da oportunidade · todos os contatos são fictícios');$('#schedule').onclick=()=>schedule(id);$('#go-tasks').onclick=()=>{taskSearch=d.company;taskOnly=false;close();nav('atividades');};$('#move-deal').onclick=()=>moveDialog(id);$('#link-product').onclick=()=>linkProduct(id);all('[data-task]').forEach(b=>b.onclick=()=>taskDetail(b.dataset.task));}
function moveDialog(id){const d=deals.find(d=>d.id===id);modal('Mover oportunidade',`<p><strong>${esc(d.company)}</strong></p><p class="muted">Etapa e situação são independentes. Nomes e regras precisam ser validados.</p><div class="formgrid" style="margin-top:20px"><label class="field">Etapa de destino<select id="move-stage">${stages.map(s=>`<option ${d.stage===s?'selected':''}>${esc(s)}</option>`).join('')}</select></label><label class="field">Situação<select id="move-status">${['Aberta','Ganha','Perdida'].map(s=>`<option ${d.status===s?'selected':''}>${s}</option>`).join('')}</select></label><label class="field full">Motivo / contexto<textarea id="move-note" placeholder="Registre o contexto da mudança"></textarea></label></div>${!d.product?'<div class="notice amber">Produto não vinculado. A movimentação não resolve a classificação para os indicadores.</div>':''}<div class="dialog-footer"><button class="btn" id="back-detail">Voltar à ficha</button><button class="btn primary" id="confirm-move">Confirmar movimento local</button></div>`);$('#back-detail').onclick=()=>openDeal(id);$('#confirm-move').onclick=()=>{const stage=$('#move-stage').value,status=$('#move-status').value,note=$('#move-note').value;if(status==='Perdida'&&!note.trim()){toast('Informe o contexto da perda neste exemplo. Regra proposta, a validar.');return;}move(id,stage,status,note);close();render();openDeal(id);};}
function move(id,stage,status,note='Movimento entre etapas no quadro.'){if(profile!=='manager')return;const d=deals.find(d=>d.id===id),before=d.stage;d.stage=stage;d.status=status;activityLog.push({deal:id,title:'Oportunidade movimentada',body:`${before} → ${stage}. Situação: ${status}. ${note}`});toast('Movimento registrado apenas no protótipo.');}
function baseSchedule(id){meetingDraft=null;const d=deals.find(d=>d.id===id);modal('Agendar reunião pela oportunidade',`<div class="notice"><strong>${esc(d.company)} · ${esc(d.contact)}</strong>E-mail já preenchido a partir da ficha. Escolha a identidade individual do escritório para evitar refazer o convite em outra conta.</div><form id="meeting-form"><div class="formgrid"><label class="field full">Título da reunião<input id="meeting-title" required value="Diagnóstico · ${esc(d.company)}"></label><label class="field">Membro do escritório<select id="meeting-member"><option>Gustavo Costa</option><option>Saulo Alves</option></select></label><label class="field">E-mail do lead<input id="meeting-lead" type="email" required value="${esc(d.email)}"></label><label class="field">Data<input id="meeting-date" type="date" required min="2026-11-23" value="2026-11-24"></label><label class="field">Horário · Brasília<input id="meeting-time" type="time" required value="14:00"></label><label class="field">Duração<select id="meeting-duration"><option>30 minutos</option><option>60 minutos</option></select></label><label class="field">Cenário da conexão<select id="meeting-scenario"><option value="ready">Conta conectada · simulado</option><option value="error">Falha da conexão · simulado</option></select></label></div><p class="muted" style="margin-top:14px;font-size:11px">Nomes de Saulo e Gustavo vêm do alinhamento. Todos os endereços são example.com. Disponibilidade e Google Agenda não foram consultados.</p><div class="dialog-footer"><button type="button" class="btn" id="back-detail">Voltar à ficha</button><button class="btn primary" type="submit">Revisar convite fictício →</button></div></form>`);$('#back-detail').onclick=()=>openDeal(id);$('#meeting-form').onsubmit=e=>{e.preventDefault();meetingDraft={deal:id,title:$('#meeting-title').value,member:$('#meeting-member').value,email:$('#meeting-lead').value,date:$('#meeting-date').value,time:$('#meeting-time').value,duration:$('#meeting-duration').value,error:$('#meeting-scenario').value==='error'};reviewMeeting();};}
function baseReviewMeeting(){const m=meetingDraft;modal(m.error?'Convite não criado · conexão indisponível':'Revise antes de registrar',`${m.error?'<div class="notice amber"><strong>Falha simulada na conexão com Google Agenda</strong>Nenhum convite foi criado e a oportunidade permanece sem reunião. Reconecte a conta individual antes de tentar novamente.</div>':''}<dl class="definition"><div class="full"><dt>Título</dt><dd>${esc(m.title)}</dd></div><div><dt>Organizador escolhido</dt><dd>${esc(m.member)}<br>${m.member==='Gustavo Costa'?'gustavo':'saulo'}@example.com</dd></div><div><dt>Convidado</dt><dd>${esc(m.email)}</dd></div><div><dt>Data e hora</dt><dd>${m.date} · ${m.time} · Brasília</dd></div><div><dt>Duração</dt><dd>${esc(m.duration)}</dd></div></dl><div class="notice">Ação demonstrativa: registra a reunião somente nesta sessão. Não envia convite, não consulta horários nem cria evento real.</div><div class="dialog-footer"><button class="btn" id="edit-meeting">Editar dados</button><button class="btn primary" id="confirm-meeting">${m.error?'Simular recuperação e revisar':'Registrar reunião simulada'}</button></div>`);$('#edit-meeting').onclick=()=>schedule(m.deal);$('#confirm-meeting').onclick=()=>{if(m.error){m.error=false;reviewMeeting();return;}const d=deals.find(d=>d.id===m.deal);d.meeting=true;tasks.push({id:'AGENDA-DEMO-'+(tasks.length+1),deal:d.id,title:m.title,owner:m.member,due:m.date,status:'Pendente',source:'Agenda simulada',time:m.time});activityLog.push({deal:d.id,title:'Reunião registrada · simulação',body:`${m.member} · ${m.date}, ${m.time} · convidado ${m.email}. Nenhum envio.`});render();openDeal(d.id);toast('Reunião fictícia registrada. Nenhum convite enviado.');};}
function baseLinkProduct(id){modal('Vincular produto do catálogo',`<p class="muted">Código e categoria mantêm a classificação consistente nos indicadores. Não criar classificação a partir de texto livre.</p><label class="field" style="margin-top:20px">Produto<select id="product-link"><option value="">Sem vínculo</option>${products.map(p=>`<option value="${p.id}">${esc(p.code)} · ${esc(p.name)} · ${esc(p.category)}</option>`).join('')}</select></label><div class="notice amber">A obrigatoriedade de preencher produto em cada etapa ainda precisa ser validada. Esta vinculação é apenas local.</div><div class="dialog-footer"><button class="btn primary" id="confirm-link">Vincular no exemplo</button></div>`);$('#confirm-link').onclick=()=>{deals.find(d=>d.id===id).product=$('#product-link').value||null;render();openDeal(id);toast('Produto vinculado somente ao exemplo.');};}
function taskRows(){return tasks.filter(t=>taskOwner==='Todos'||t.owner===taskOwner).filter(t=>!taskDate||t.due===taskDate).filter(t=>taskDue==='Todos'||taskDue==='Atrasadas'&&t.due<today&&t.status!=='Concluída'||taskDue==='Hoje'&&t.due===today||taskDue==='Próximas'&&t.due>today||taskDue==='Concluídas'&&t.status==='Concluída').filter(t=>!taskSearch||[t.title,deals.find(d=>d.id===t.deal)?.company,t.id].join(' ').toLowerCase().includes(taskSearch.toLowerCase()));}
function activities(){const rows=taskRows();return `<div class="toolbar"><input type="search" id="task-search" value="${esc(taskSearch)}" placeholder="Buscar atividade, oportunidade ou ID" aria-label="Buscar atividade"><label class="field">Responsável<select id="task-owner">${['Todos','Gustavo Costa','Saulo Alves'].map(v=>`<option ${taskOwner===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">Vencimento<select id="task-due">${['Todos','Atrasadas','Hoje','Próximas','Concluídas'].map(v=>`<option ${taskDue===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">Prazo exato<input id="task-date" type="date" value="${taskDate}"></label><button class="btn" data-clear-tasks>Limpar filtros</button></div><div class="board-summary"><strong>${rows.length} atividades encontradas</strong>${tag('ClickUp · vínculo demonstrativo')}</div><div class="panel mobile-stack"><div class="panel-head"><div><h2>O trabalho comercial, reunido</h2><p class="subtitle">23 nov 2026 · referência fixa da demonstração</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Atividade / oportunidade</th><th>Responsável</th><th>Prazo</th><th>Vínculo</th><th>Conferir</th></tr></thead><tbody>${rows.map(t=>{const d=deals.find(d=>d.id===t.deal);return `<tr><td data-label="Atividade"><button class="row-link" data-task="${t.id}">${esc(t.title)}</button><small>${esc(d.company)}</small></td><td data-label="Responsável">${esc(t.owner)}</td><td data-label="Prazo">${t.due}${t.time?' · '+t.time:''}<small>${tag(t.status==='Concluída'?'Concluída':t.due<today?'Atrasada':t.due===today?'Hoje':'Próxima',t.status==='Concluída'?'green':t.due<today?'red':'')}</small></td><td data-label="Vínculo">${esc(t.source)}<small>${esc(t.id)} · exemplo</small></td><td data-label="Conferir"><button class="btn" data-open="${d.id}">Abrir ficha ↗</button></td></tr>`;}).join('')||'<tr><td colspan="5">Nenhuma atividade com estes filtros. Limpe o recorte para ver as demais.</td></tr>'}</tbody></table></div></div><div class="notice">Tarefas do ClickUp e reuniões aparecem no mesmo contexto comercial, sem prometer sincronização já existente. Responsáveis usam identidades individuais; integração, escopo e sentido da sincronização precisam de validação técnica.</div>`;}
function baseTaskDetail(id){const t=tasks.find(t=>t.id===id),d=deals.find(d=>d.id===t.deal);modal(esc(t.title),`<dl class="definition"><div><dt>Oportunidade</dt><dd>${esc(d.company)}</dd></div><div><dt>Responsável</dt><dd>${esc(t.owner)}</dd></div><div><dt>Prazo</dt><dd>${t.due}${t.time?' · '+t.time:''}</dd></div><div><dt>Situação</dt><dd>${esc(t.status)}</dd></div><div><dt>Origem / identificação</dt><dd>${esc(t.source)} · ${esc(t.id)}</dd></div></dl><div class="notice">Vínculo fictício. Não foi consultada nem alterada nenhuma tarefa real no ClickUp.</div><div class="dialog-footer"><button class="btn" id="task-deal">Abrir oportunidade</button><button class="btn primary manager-only" id="task-complete">${t.status==='Concluída'?'Reabrir no exemplo':'Concluir no exemplo'}</button></div>`);$('#task-deal').onclick=()=>openDeal(d.id);$('#task-complete').onclick=()=>{if(profile!=='manager')return;t.status=t.status==='Concluída'?'Pendente':'Concluída';close();render();toast('Situação alterada apenas na simulação.');};}
function catalog(){const rows=products.filter(p=>[p.code,p.name,p.category].join(' ').toLowerCase().includes(catalogSearch.toLowerCase()));return `<div class="toolbar"><input type="search" id="catalog-search" value="${esc(catalogSearch)}" placeholder="Buscar código, produto ou categoria" aria-label="Buscar produto"><button class="btn primary manager-only spacer" data-create-product>+ Novo produto · exemplo</button></div><div class="notice amber"><strong>${deals.filter(d=>!d.product).length} oportunidades sem produto no cenário</strong>A cobertura incompleta relatada afeta a leitura por centro de custo. Oportunidades sem vínculo aparecem em “Não classificado” nos Insights.</div><div class="panel mobile-stack"><div class="panel-head"><h2>Catálogo padronizado</h2>${tag('Códigos e categorias fictícios')}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Código</th><th>Produto</th><th>Categoria</th><th>Centro de custo</th></tr></thead><tbody>${rows.map(p=>`<tr><td data-label="Código"><strong>${esc(p.code)}</strong></td><td data-label="Produto">${esc(p.name)}</td><td data-label="Categoria">${esc(p.category)}</td><td data-label="Centro de custo">${esc(p.center)}</td></tr>`).join('')}</tbody></table></div></div><div class="two-col" style="margin-top:20px"><section class="panel panel-body"><h2>Padronização no ponto de cadastro</h2><p class="subtitle">Código e categoria sustentam os indicadores. Os valores reais e a relação com centro de custo devem ser validados; o exemplo usa identificadores DEMO.</p></section><section class="panel panel-body"><h2>Governança · hipótese</h2><p class="subtitle">Hoje a padronização foi descrita como orientação interna. Aprovação obrigatória por Saulo foi uma sugestão de Cleiton, não uma regra confirmada. Não há fila de aprovação imposta nesta proposta.</p></section></div>`;}
function baseCreateProduct(){modal('Novo produto · estrutura proposta',`<p class="muted">Campos propostos para preservar classificação; obrigatoriedade e catálogo real a validar com Saulo e Gustavo.</p><form id="product-form"><div class="formgrid" style="margin-top:20px"><label class="field full">Nome<input id="new-product-name" required></label><label class="field">Código padronizado<input id="new-product-code" required placeholder="DEMO-004"></label><label class="field">Categoria<select id="new-product-category"><option>Consultivo</option><option>Societário</option><option>Propriedade intelectual</option></select></label><label class="field full">Centro de custo<select id="new-product-center"><option>Consultivo empresarial</option><option>Societário</option><option>Propriedade intelectual</option></select></label></div><p class="form-error" id="product-error" role="alert"></p><div class="dialog-footer"><button class="btn primary" type="submit">Adicionar ao catálogo fictício</button></div></form>`);$('#product-form').onsubmit=e=>{e.preventDefault();const code=$('#new-product-code').value.trim();if(products.some(p=>p.code.toLowerCase()===code.toLowerCase())){$('#product-error').textContent='Já existe um produto com este código no exemplo.';return;}products.push({id:'p'+Date.now(),name:$('#new-product-name').value.trim(),code,category:$('#new-product-category').value,center:$('#new-product-center').value});close();render();toast('Produto adicionado apenas ao catálogo fictício.');};}
const sdrStats=[{name:'CorpLaw',source:'Painel de SDR anterior ao Vale',conversations:38,meetings:6,cost:42.80,signal:'Revisar resposta sobre escopo',health:'Revisão sugerida'},{name:'Vale',source:'Painel específico do Vale',conversations:24,meetings:4,cost:28.40,signal:'Verificar passagem para reunião',health:'Acompanhamento'}];
function sdr(){const rows=sdrStats.filter(s=>sdrScope==='Todos'||s.name===sdrScope);return `<div class="toolbar"><label class="field">Origem / unidade<select id="sdr-scope">${['Todos','CorpLaw','Vale'].map(v=>`<option ${sdrScope===v?'selected':''}>${v}</option>`).join('')}</select></label><span class="muted">Últimos 7 dias · janela fictícia: 17–23 nov 2026</span><button class="btn manager-only spacer" data-permissions>Ver hipótese de acesso</button></div><div class="three-col"><div class="metric"><span class="muted">Conversas no recorte</span><strong class="number">${rows.reduce((s,r)=>s+r.conversations,0)}</strong></div><div class="metric"><span class="muted">Reuniões no recorte</span><strong class="number">${rows.reduce((s,r)=>s+r.meetings,0)}</strong></div><div class="metric"><span class="muted">Custo estimado · exemplo</span><strong class="number">${rows.reduce((s,r)=>s+r.cost,0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'})}</strong></div></div><div class="panel mobile-stack" style="margin-top:22px"><div class="panel-head"><h2>Dois painéis, uma visão de gestão</h2>${tag('Métricas demonstrativas','amber')}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>SDR / origem</th><th>Comportamento a conferir</th><th>Conversas</th><th>Gestão</th></tr></thead><tbody>${rows.map(s=>`<tr><td data-label="SDR"><strong>SDR ${s.name}</strong><small>${s.source}</small></td><td data-label="Comportamento">${s.signal}<small>${tag(s.health,'amber')}</small></td><td data-label="Conversas">${s.conversations}<small>${s.meetings} reuniões</small></td><td data-label="Gestão"><div class="actions"><button class="btn" data-conversation="${s.name}">Conversas ↗</button><button class="btn manager-only" data-behavior="${s.name}">Editar comportamento</button></div></td></tr>`).join('')}</tbody></table></div></div><div class="notice">Os nomes “SDR CorpLaw” e “SDR Vale” identificam os dois contextos do briefing, não um inventário validado de agentes. Custos e contagens são fictícios. Edição e visibilidade dependem da futura matriz de permissões.</div>`;}
let behaviors={CorpLaw:'Confirmar demanda e sugerir reunião quando houver interesse.',Vale:'Conferir conclusão do Raio X antes de sugerir a reunião.'};
function conversation(name){modal('Conversa · SDR '+esc(name),`<p class="muted">Conversa inteiramente fictícia para inspecionar o comportamento.</p><div class="sdr-chat"><strong>Lead · exemplo</strong><p>Concluí o Raio X. Como podemos conversar sobre o resultado?</p></div><div class="sdr-chat answer"><strong>SDR ${esc(name)} · exemplo</strong><p>Podemos organizar uma reunião com um membro do escritório. Qual horário funciona para você?</p></div><div class="notice amber"><strong>Ponto de revisão</strong>Conferir a passagem de contexto para a oportunidade e evitar prometer escopo jurídico automaticamente. Este sinal é uma hipótese de inspeção, não avaliação de um atendimento real.</div><div class="dialog-footer"><button class="btn manager-only" id="edit-behavior">Editar orientação · simulado</button><button class="btn primary" id="close-chat">Concluir leitura</button></div>`);$('#close-chat').onclick=close;$('#edit-behavior').onclick=()=>behavior(name);}
function behavior(name){if(profile!=='manager')return;modal('Orientação do SDR '+esc(name),`<label class="field">Comportamento proposto<textarea id="behavior-text">${esc(behaviors[name])}</textarea></label><div class="notice amber">Hipótese de permissão: gestão pode editar, comercial pode consultar. Alterações aqui não publicam configurações em nenhum SDR real.</div><div class="dialog-footer"><button class="btn primary" id="save-behavior">Salvar rascunho local</button></div>`);$('#save-behavior').onclick=()=>{behaviors[name]=$('#behavior-text').value;close();toast('Rascunho local salvo. Nenhum SDR foi atualizado.');};}
function segmentEligible(d){return d.rx&&!d.meeting&&d.status==='Aberta'&&d.consent;}
function baseSegments(){const rows=deals.filter(segmentEligible),rxCount=deals.filter(d=>d.rx).length;return `<section class="segment-hero"><div><p class="eyebrow">Segmento de exemplo</p><h2>Fez o Raio X.<br>Ainda não marcou reunião.</h2><p>Lista de análise para decidir a próxima abordagem. Nenhum disparo disponível.</p></div><div><span class="number">${rows.length}</span><p>elegíveis no cenário fictício</p></div></section><div class="two-col" style="margin-top:20px"><section class="panel"><div class="panel-head"><h2>Condições do segmento</h2>${tag('Todas · E','teal')}</div><div class="panel-body"><div class="seg-rule"><b>01</b>Raio X concluído = Sim</div><div class="seg-rule"><b>02</b>Reunião marcada = Não</div><div class="seg-rule"><b>03</b>Situação = Aberta</div><div class="seg-rule"><b>04</b>Sem bloqueio de contato · hipótese</div><div class="notice">Elegibilidade usa dados fictícios. Consentimento, base de contato, janela e política de abordagem precisam de validação antes de qualquer campanha.</div><button class="btn" data-segment-filter>Ver este recorte no funil ↗</button></div></section><section class="panel"><div class="panel-head"><h2>Quem ficou de fora</h2></div><div class="panel-body">${deals.filter(d=>d.rx&&!segmentEligible(d)).map(d=>`<div style="margin-bottom:18px"><strong>${esc(d.company)}</strong><p class="muted">${d.meeting?'Reunião já marcada':d.status!=='Aberta'?'Situação '+d.status:''}${!d.consent?' · não contatar':''}</p></div>`).join('')||'<p>Nenhuma exclusão neste cenário.</p>'}<p class="muted">${rxCount} fizeram o Raio X no exemplo. A lista é recalculada quando uma reunião é registrada localmente.</p></div></section></div><div class="panel mobile-stack" style="margin-top:20px"><div class="panel-head"><h2>Elegíveis para análise</h2>${tag('Sem envio','amber')}</div><table class="data-table"><thead><tr><th>Oportunidade</th><th>Contato</th><th>Responsável</th><th>Próximo passo</th></tr></thead><tbody>${rows.map(d=>`<tr><td data-label="Oportunidade"><strong>${esc(d.company)}</strong></td><td data-label="Contato">${esc(d.contact)}</td><td data-label="Responsável">${esc(d.owner)}</td><td data-label="Próximo passo"><button class="btn" data-open="${d.id}">Conferir ficha ↗</button></td></tr>`).join('')||'<tr><td colspan="4">Nenhuma oportunidade elegível.</td></tr>'}</tbody></table></div><div class="notice amber"><strong>Campanha e Meta: validação técnica pendente</strong>Esta entrega demonstra seleção e exclusões. Cadência por e-mail é secundária. Não há botão de envio, integração Meta nem promessa de disparo operacional.</div>`;}
function settings(){return `<div class="two-col" style="margin-top:22px"><section class="panel"><div class="panel-head"><h2>Funis e etapas</h2><button class="btn manager-only" data-new-funnel>+ Criar funil</button></div><div class="panel-body config-list">${pipelines.map(p=>`<div class="config-row"><div><strong>${esc(p.name)}</strong><p class="muted">${p.stages.map(esc).join(' → ')}</p></div></div>`).join('')}<button class="btn manager-only" data-config-funnel>Editar etapas do funil atual</button><p class="subtitle">Estrutura inicial ilustrativa. Não presume as etapas reais usadas no Pipedrive.</p></div></section><section class="panel"><div class="panel-head"><h2>Integrações e acesso</h2></div><div class="panel-body"><div class="config-list">${['Google Agenda · identidade individual','ClickUp · atividades comerciais','Meta · gestão e campanhas'].map(t=>`<div class="config-row"><span>${t}</span>${tag('Não conectado','amber')}</div>`).join('')}</div><button class="btn link" data-permissions>Ver proposta de permissões →</button><div class="notice">Nenhuma chave, conta ou banco é solicitado. Integrações são representações de design.</div></div></section></div>`;}
function funnelConfig(newFunnel=false){if(profile!=='manager')return;modal(newFunnel?'Criar funil · hipótese':'Editar funil e etapas',`<p class="muted">A nomenclatura deve ser validada com Saulo. Alterações só afetam esta sessão de design.</p><form id="funnel-form"><label class="field" style="margin-top:18px">Nome do funil<input id="funnel-name" required value="${newFunnel?'':esc(pipeline)}"></label><label class="field" style="margin-top:15px">Etapas · uma por linha<textarea id="funnel-stages" required>${newFunnel?'Entrada\nQualificação\nProposta':stages.join('\n')}</textarea></label><p class="form-error" id="funnel-error" role="alert"></p><div class="notice amber">Ao renomear uma etapa usada, o protótipo mantém as oportunidades nela. Remoção de etapa ocupada exige migração, ainda não demonstrada.</div><div class="dialog-footer"><button class="btn primary" type="submit">Salvar estrutura local</button></div></form>`);$('#funnel-form').onsubmit=e=>{e.preventDefault();const name=$('#funnel-name').value.trim(),next=$('#funnel-stages').value.split('\n').map(v=>v.trim()).filter(Boolean);if(!name||next.length<1||next.length>6||new Set(next).size!==next.length){$('#funnel-error').textContent='Use de uma a seis etapas, com nomes distintos.';return;}const current=pipelines.find(p=>p.name===pipeline);if(pipelines.some(p=>p.name===name&&(newFunnel||p!==current))){$('#funnel-error').textContent='Nome já usado neste exemplo.';return;}if(newFunnel){if(pipelines.some(p=>p.name===name)){$('#funnel-error').textContent='Nome já usado neste exemplo.';return;}pipelines.push({name,stages:next});}else{if(next.length<stages.length&&deals.some(d=>stages.indexOf(d.stage)>=next.length&&(d.pipeline||'Novos negócios')===pipeline)){$('#funnel-error').textContent='A última etapa tem oportunidades. Mantenha-a neste exemplo.';return;}deals.filter(d=>(d.pipeline||'Novos negócios')===pipeline).forEach(d=>{const index=stages.indexOf(d.stage);d.stage=next[index]||d.stage;d.pipeline=name;});current.name=name;current.stages=next;}pipeline=name;stages=[...next];close();nav('funis');toast('Estrutura salva apenas na sessão do protótipo.');};}
function permissions(){modal('Permissões · hipótese para validação',`<p class="muted">A identidade de cada pessoa já existe no painel; o alcance de cada perfil comercial ainda precisa ser definido com Saulo e Gustavo.</p><div class="table-wrap" style="margin-top:20px"><table class="data-table"><thead><tr><th>Ação</th><th>Comercial · hipótese</th><th>Gestão · hipótese</th></tr></thead><tbody>${[['Consultar oportunidades e atividades','Sim','Sim'],['Mover e editar oportunidades','A validar · bloqueado nesta simulação','Sim no exemplo'],['Criar funis e dashboards','A validar · bloqueado nesta simulação','Sim no exemplo'],['Ver conversas de SDR','Sim no exemplo','Sim no exemplo'],['Editar comportamento e catálogo','A validar · bloqueado nesta simulação','Sim no exemplo']].map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="notice amber">O seletor de perfil demonstra visibilidade e bloqueios locais; não é mecanismo de autorização. Escopo por carteira, dados sensíveis, custos e edição devem ser definidos antes da implementação.</div>`,'wide');}
function insights(){const dash=savedDashboards.find(d=>d.id===activeDash)||savedDashboards[0],oldSearch=search;search='';const rows=filtered(dash.rules,dash.logic);search=oldSearch;const groupLabel={stage:'Etapa',owner:'Responsável',center:'Centro de custo'}[dash.group];const groups={};rows.forEach(d=>{const k=dash.group==='center'?(products.find(p=>p.id===d.product)?.center||'Não classificado'):valueOf(d,dash.group);groups[k]=(groups[k]||0)+(dash.metric==='count'?1:d.value);});const max=Math.max(1,...Object.values(groups));return `<div class="toolbar"><label class="field">Dashboard salvo<select id="dashboard-choice">${savedDashboards.map(d=>`<option value="${d.id}" ${d.id===dash.id?'selected':''}>${esc(d.name)}</option>`).join('')}</select></label><button class="btn manager-only" data-edit-dashboard>Editar dashboard</button><button class="btn primary manager-only spacer" data-new-dashboard>+ Criar com filtros do CRM</button></div>${filterChips(dash.rules,dash.logic)}<div class="board-summary"><span><strong>${rows.length} oportunidades</strong> neste dashboard</span>${tag('Dados fictícios','amber')}</div><div class="two-col"><section class="panel"><div class="panel-head"><div><h2>${esc(dash.name)}</h2><p class="subtitle">${dash.metric==='count'?'Quantidade de oportunidades':'Valor das oportunidades'} por ${groupLabel.toLowerCase()}</p></div></div><div class="panel-body">${Object.entries(groups).map(([k,v])=>`<div class="bar-row"><span>${esc(k)}</span><div class="bar"><span style="width:${v/max*100}%"></span></div><strong>${dash.metric==='count'?v:money(v)}</strong></div>`).join('')||'<p class="muted">Nenhum dado atende ao recorte salvo.</p>'}</div></section><aside class="panel"><div class="panel-head"><h2>Contexto do indicador</h2></div><div class="panel-body"><p>O recorte salvo acompanha o dashboard. Edite nome, métrica e agrupamento sem perder as condições usadas para construí-lo.</p><div class="notice amber"><strong>${rows.filter(d=>!d.product).length} sem produto vinculado</strong>Centro de custo desconhecido fica em “Não classificado”. Não é excluído silenciosamente do valor total.</div><button class="btn" data-dashboard-funnel>Ver oportunidades do recorte ↗</button><p class="subtitle">Insights existentes continuam como subárea irmã. Esta tela propõe um exemplo de criação e edição, sem reconstruir todos os indicadores atuais.</p></div></aside></div>`;}
function dashboardForm(edit=false){if(profile!=='manager')return;const old=edit?savedDashboards.find(d=>d.id===activeDash):null;modal(edit?'Editar dashboard salvo':'Salvar recorte em Insights',`${filterChips(old?.rules||rules,old?.logic||logic)}<form id="dashboard-form"><div class="formgrid"><label class="field full">Nome do dashboard<input required id="dashboard-name" value="${esc(old?.name||'Raio X · oportunidades a acompanhar')}"></label><label class="field">Indicador<select id="dashboard-metric"><option value="value" ${old?.metric==='value'?'selected':''}>Valor das oportunidades</option><option value="count" ${old?.metric==='count'?'selected':''}>Quantidade de oportunidades</option></select></label><label class="field">Agrupar por<select id="dashboard-group">${[['stage','Etapa'],['owner','Responsável'],['center','Centro de custo']].map(([k,v])=>`<option value="${k}" ${old?.group===k?'selected':''}>${v}</option>`).join('')}</select></label></div><div class="notice">Filtros salvos junto à leitura. Persistência, compartilhamento e permissões são hipóteses; esta gravação é só local e se perde ao recarregar.</div><div class="dialog-footer"><button class="btn primary" type="submit">Salvar dashboard no exemplo</button></div></form>`);$('#dashboard-form').onsubmit=e=>{e.preventDefault();const record={id:old?.id||'dash'+Date.now(),name:$('#dashboard-name').value.trim(),rules:structuredClone(old?.rules||rules),logic:old?.logic||logic,metric:$('#dashboard-metric').value,group:$('#dashboard-group').value};if(old)Object.assign(old,record);else savedDashboards.push(record);activeDash=record.id;close();nav('insights');toast('Dashboard e filtros salvos na sessão fictícia.');};}
function render(){document.body.dataset.profile=profile;$('#app').innerHTML=shell();bind();}
function bind(){all('[data-nav]').forEach(b=>b.onclick=e=>{e.preventDefault();nav(b.dataset.nav);});$('#profile').onchange=e=>{profile=e.target.value;render();toast('Acesso ilustrativo. Matriz real de permissões a validar.');};all('[data-open]').forEach(b=>b.onclick=()=>openDeal(b.dataset.open));all('[data-task]').forEach(b=>b.onclick=()=>taskDetail(b.dataset.task));all('[data-filters]').forEach(b=>b.onclick=()=>filterDialog(true));all('[data-save-insights]').forEach(b=>b.onclick=()=>dashboardForm());$('#pipeline')?.addEventListener('change',e=>{pipeline=e.target.value;stages=[...pipelines.find(p=>p.name===pipeline).stages];render();});$('#deal-search')?.addEventListener('input',e=>{search=e.target.value;const pos=e.target.selectionStart;render();$('#deal-search').focus();$('#deal-search').setSelectionRange(pos,pos);});all('[data-drag]').forEach(el=>el.ondragstart=e=>{if(profile!=='manager'){e.preventDefault();return;}e.dataTransfer.setData('text/plain',el.dataset.drag);});all('[data-lane]').forEach(el=>{el.ondragover=e=>{e.preventDefault();if(profile==='manager')el.classList.add('dragover');};el.ondragleave=()=>el.classList.remove('dragover');el.ondrop=e=>{e.preventDefault();const id=e.dataTransfer.getData('text/plain'),d=deals.find(d=>d.id===id);if(d){move(id,el.dataset.lane,d.status);render();}};});all('[data-config-funnel]').forEach(b=>b.onclick=()=>funnelConfig());all('[data-new-funnel]').forEach(b=>b.onclick=()=>funnelConfig(true));all('[data-permissions]').forEach(b=>b.onclick=permissions);all('[data-create-product]').forEach(b=>b.onclick=createProduct);$('#catalog-search')?.addEventListener('input',e=>{catalogSearch=e.target.value;render();$('#catalog-search').focus();});$('#task-search')?.addEventListener('input',e=>{taskSearch=e.target.value;render();$('#task-search').focus();});for(const [id,set]of [['task-owner',v=>taskOwner=v],['task-due',v=>taskDue=v],['task-date',v=>taskDate=v]])$('#'+id)?.addEventListener('change',e=>{set(e.target.value);render();});all('[data-clear-tasks]').forEach(b=>b.onclick=()=>{taskOwner='Todos';taskDue='Todos';taskDate='';taskSearch='';render();});$('#sdr-scope')?.addEventListener('change',e=>{sdrScope=e.target.value;render();});all('[data-conversation]').forEach(b=>b.onclick=()=>conversation(b.dataset.conversation));all('[data-behavior]').forEach(b=>b.onclick=()=>behavior(b.dataset.behavior));all('[data-segment-filter]').forEach(b=>b.onclick=()=>{rules=[{field:'rx',op:'eq',value:'Sim'},{field:'meeting',op:'eq',value:'Não'},{field:'status',op:'eq',value:'Aberta'}];logic='all';search='';nav('funis');toast('Recorte de Raio X e reunião aplicado. Bloqueios de contato continuam visíveis na ficha.');});$('#dashboard-choice')?.addEventListener('change',e=>{activeDash=e.target.value;render();});all('[data-edit-dashboard]').forEach(b=>b.onclick=()=>dashboardForm(true));all('[data-new-dashboard]').forEach(b=>b.onclick=()=>dashboardForm());all('[data-dashboard-funnel]').forEach(b=>b.onclick=()=>{const dash=savedDashboards.find(d=>d.id===activeDash);rules=structuredClone(dash.rules);logic=dash.logic;search='';nav('funis');});}
window.designState=()=>({section,profile,pipeline,stages:[...stages],rules:structuredClone(rules),logic,visible:filtered().map(d=>d.id),deals:structuredClone(deals),tasks:structuredClone(tasks),taskFiltered:taskRows().map(t=>t.id),products:structuredClone(products),dashboards:structuredClone(savedDashboards),activeDash,eligible:deals.filter(segmentEligible).map(d=>d.id),integrations:false});
/* Percursos da revisão: executado no mesmo escopo local do protótipo. */
let returnTaskId=null,productReturnId=null,opportunitySequence=8;
let campaign={step:'publico',selected:null,reviewed:false,text:'Olá, {contato}. Você concluiu o Raio X da {empresa}. Podemos combinar uma conversa com o escritório sobre o resultado?',approved:false,queue:[],signature:''};
const campaignSignature=()=>JSON.stringify(deals.map(d=>[d.id,d.contact,d.company,d.rx,d.meeting,d.status,d.consent]));
function invalidateCampaign(){campaign.reviewed=false;campaign.approved=false;campaign.queue=[];campaign.step='publico';}
function openDeal(id){baseOpenDeal(id);const box=$('.detail-actions');if(profile==='manager'){const button=document.createElement('button');button.className='btn';button.id='edit-opportunity';button.textContent='Editar oportunidade';button.onclick=()=>opportunityForm(id);box.append(button);}const locate=document.createElement('button');locate.className='btn link';locate.id='locate-opportunity';locate.textContent='Localizar no quadro →';locate.onclick=()=>{const d=deals.find(d=>d.id===id);pipeline=d.pipeline||'Novos negócios';stages=[...pipelines.find(p=>p.name===pipeline).stages];rules=[];search=d.company;close();nav('funis');toast('Quadro ajustado para mostrar esta oportunidade.');};$('.dialog-body').append(locate);}
function opportunityForm(id=null){if(profile!=='manager')return;const old=deals.find(d=>d.id===id);const d=old||{company:'',contact:'',email:'',phone:'',owner:'Gustavo Costa',origin:'Site',stage:stages[0],status:'Aberta',value:0,rx:false,meeting:false,priority:'Normal',note:'',product:null};
modal(old?'Editar oportunidade':'Criar oportunidade',`<div class="notice">Registro fictício no funil <strong>${esc(pipeline)}</strong>. Nesta demonstração, nome da oportunidade é necessário para identificar o cartão. Obrigatoriedade dos demais campos e permissões precisam de validação com Saulo e Gustavo.</div><form id="opportunity-form"><div class="formgrid"><label class="field full">Nome da oportunidade · necessário no exemplo<input id="op-company" required value="${esc(d.company)}" placeholder="Ex.: Empresa Horizonte · novo projeto"></label><label class="field">Contato<input id="op-contact" value="${esc(d.contact)}" placeholder="Nome fictício"></label><label class="field">E-mail do lead<input id="op-email" type="email" value="${esc(d.email)}" placeholder="contato@example.com"></label><label class="field">Telefone · fictício<input id="op-phone" value="${esc(d.phone)}" placeholder="+55 (00) 00000-0000"></label><label class="field">Responsável individual<select id="op-owner">${['Gustavo Costa','Saulo Alves'].map(v=>`<option ${d.owner===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">Origem<select id="op-origin">${['Site','Raio X','Indicação'].map(v=>`<option ${d.origin===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">Valor da oportunidade · R$<input id="op-value" type="number" min="0" step="0.01" value="${d.value}"></label><label class="field">Etapa<select id="op-stage">${stages.map(v=>`<option ${d.stage===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label><label class="field">Situação<select id="op-status">${['Aberta','Ganha','Perdida'].map(v=>`<option ${d.status===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">Raio X concluído · personalizado<select id="op-rx"><option value="no" ${!d.rx?'selected':''}>Não</option><option value="yes" ${d.rx?'selected':''}>Sim</option></select></label><label class="field">Reunião marcada · personalizado<select id="op-meeting"><option value="no" ${!d.meeting?'selected':''}>Não</option><option value="yes" ${d.meeting?'selected':''}>Sim</option></select></label><label class="field">Prioridade · personalizado<select id="op-priority">${['Normal','Alta'].map(v=>`<option ${d.priority===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">Produto do catálogo<select id="op-product"><option value="">Sem produto vinculado</option>${products.map(p=>`<option value="${p.id}" ${d.product===p.id?'selected':''}>${esc(p.code)} · ${esc(p.name)}</option>`).join('')}</select></label><label class="field full">Anotações<textarea id="op-notes">${esc(d.note)}</textarea></label></div><div class="dialog-footer"><button class="btn" type="button" id="cancel-opportunity">Cancelar</button><button class="btn primary" type="submit">${old?'Salvar alterações locais':'Criar cartão fictício'}</button></div></form>`,'wide');
$('#cancel-opportunity').onclick=()=>old?openDeal(id):close();$('#opportunity-form').onsubmit=e=>{e.preventDefault();const fields={company:$('#op-company').value.trim(),contact:$('#op-contact').value.trim(),email:$('#op-email').value.trim(),phone:$('#op-phone').value.trim(),owner:$('#op-owner').value,origin:$('#op-origin').value,value:Number($('#op-value').value),stage:$('#op-stage').value,status:$('#op-status').value,rx:$('#op-rx').value==='yes',meeting:$('#op-meeting').value==='yes',priority:$('#op-priority').value,product:$('#op-product').value||null,note:$('#op-notes').value.trim()};if(!fields.company){$('#op-company').focus();return;}let record;if(old){Object.assign(old,fields);record=old;}else{record={...fields,id:'d'+opportunitySequence++,pipeline,consent:true,sdr:'Não atribuído',activity:'Definir próxima atividade',due:today};deals.push(record);}activityLog.push({deal:record.id,title:old?'Oportunidade editada':'Oportunidade criada',body:'Gustavo Costa · alterações apenas nesta sessão.'});invalidateCampaign();render();openDeal(record.id);toast(old?'Ficha e cartão atualizados no exemplo.':'Oportunidade criada. Use Localizar no quadro para conferir.');};}
function linkProduct(id){baseLinkProduct(id);const box=$('.dialog-footer');const create=document.createElement('button');create.className='btn';create.id='create-product-from-deal';create.textContent='+ Cadastrar produto nesta ficha';create.onclick=()=>createProduct(id);box.prepend(create);const back=document.createElement('button');back.className='btn link';back.textContent='Voltar à mesma oportunidade';back.onclick=()=>openDeal(id);box.prepend(back);}
function createProduct(context=null){if(profile!=='manager')return;productReturnId=typeof context==='string'?context:null;const returnId=productReturnId;modal(returnId?'Cadastrar e vincular produto':'Novo produto · estrutura proposta',`${returnId?`<div class="notice"><strong>${esc(deals.find(d=>d.id===returnId).company)}</strong>Ao salvar, o produto será vinculado a esta mesma oportunidade.</div>`:''}<p class="muted">Nome, código, categoria e centro de custo são solicitados no exemplo para demonstrar classificação completa. Obrigatoriedade e relação entre os campos precisam de validação. Aprovação obrigatória por Saulo continua hipótese, sem bloqueio imposto aqui.</p><form id="product-form"><div class="formgrid" style="margin-top:20px"><label class="field full">Nome<input id="new-product-name" required></label><label class="field">Código padronizado<input id="new-product-code" required placeholder="DEMO-004"></label><label class="field">Categoria<select id="new-product-category"><option>Consultivo</option><option>Societário</option><option>Propriedade intelectual</option></select></label><label class="field full">Centro de custo<select id="new-product-center"><option>Consultivo empresarial</option><option>Societário</option><option>Propriedade intelectual</option></select></label></div><p class="form-error" id="product-error" role="alert"></p><div class="dialog-footer"><button class="btn" type="button" id="cancel-product">${returnId?'Voltar à ficha sem salvar':'Cancelar'}</button><button class="btn primary" type="submit">${returnId?'Cadastrar e vincular no exemplo':'Adicionar ao catálogo fictício'}</button></div></form>`);$('#cancel-product').onclick=()=>returnId?openDeal(returnId):close();$('#product-form').onsubmit=e=>{e.preventDefault();const name=$('#new-product-name').value.trim(),code=$('#new-product-code').value.trim();if(!name||!code)return;if(products.some(p=>p.code.toLowerCase()===code.toLowerCase())){$('#product-error').textContent='Já existe um produto com este código no exemplo. Use um código distinto ou volte para selecionar o produto existente.';$('#new-product-code').focus();return;}const product={id:'p'+Date.now(),name,code,category:$('#new-product-category').value,center:$('#new-product-center').value};products.push(product);if(returnId){deals.find(d=>d.id===returnId).product=product.id;activityLog.push({deal:returnId,title:'Produto cadastrado e vinculado',body:`${code} · ${name} · ${product.category} · ${product.center}.`});}render();if(returnId)openDeal(returnId);else close();toast(returnId?'Produto cadastrado e vinculado à mesma ficha.':'Produto adicionado somente ao catálogo fictício.');};}
function taskDetail(id){baseTaskDetail(id);const task=tasks.find(t=>t.id===id);const box=$('.dialog-footer');if(profile==='manager'){const b=document.createElement('button');b.className='btn primary';b.id='schedule-from-task';b.textContent='Agendar pela tarefa';b.onclick=()=>schedule(task.deal,id);box.prepend(b);}if(task.meetingResult){const note=document.createElement('div');note.className='notice';note.id='task-meeting-result';note.innerHTML=`<strong>Reunião registrada na simulação</strong>${esc(task.meetingResult.title)}<br>${esc(task.meetingResult.member)} · ${esc(task.meetingResult.date)} às ${esc(task.meetingResult.time)} · Brasília<br>Convidado: ${esc(task.meetingResult.email)}<br>Nenhum convite real foi criado. A tarefa mantém sua situação; reunião e conclusão são ações distintas.`;box.before(note);}}
function schedule(id,taskId=null){returnTaskId=taskId;const d=deals.find(d=>d.id===id),t=tasks.find(t=>t.id===taskId);meetingDraft=null;modal('Agendar reunião pela '+(t?'tarefa':'oportunidade'),`<div class="notice"><strong>${esc(d.company)} · ${esc(d.contact)}</strong>${t?`Tarefa de origem: ${esc(t.title)} · ${esc(t.id)}<br>`:''}E-mail preenchido a partir da ficha. Escolha a identidade individual do escritório.</div><form id="meeting-form"><div class="formgrid"><label class="field full">Título da reunião<input id="meeting-title" required value="Diagnóstico · ${esc(d.company)}"></label><label class="field">Membro do escritório<select id="meeting-member">${['Gustavo Costa','Saulo Alves'].map(v=>`<option ${t?.owner===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">E-mail do lead<input id="meeting-lead" type="email" required value="${esc(d.email)}"></label><label class="field">Data<input id="meeting-date" type="date" required min="2026-11-23" value="2026-11-24"></label><label class="field">Horário · Brasília<input id="meeting-time" type="time" required value="14:00"></label><label class="field">Duração<select id="meeting-duration"><option>30 minutos</option><option>60 minutos</option></select></label><label class="field">Cenário da conexão<select id="meeting-scenario"><option value="ready">Conta conectada · simulado</option><option value="error">Falha da conexão · simulado</option></select></label></div><p class="muted" style="margin-top:14px;font-size:11px">Nomes do alinhamento, e-mails example.com. Sem consulta de disponibilidade. Campos necessários neste exemplo não definem a regra final do CRM.</p><div class="dialog-footer"><button type="button" class="btn" id="back-detail">Voltar à ${t?'tarefa':'ficha'}</button><button class="btn primary" type="submit">Revisar convite fictício →</button></div></form>`);$('#back-detail').onclick=()=>t?taskDetail(t.id):openDeal(id);$('#meeting-form').onsubmit=e=>{e.preventDefault();meetingDraft={deal:id,task:taskId,title:$('#meeting-title').value,member:$('#meeting-member').value,email:$('#meeting-lead').value,date:$('#meeting-date').value,time:$('#meeting-time').value,duration:$('#meeting-duration').value,error:$('#meeting-scenario').value==='error'};reviewMeeting();};}
function reviewMeeting(){const m=meetingDraft;modal(m.error?'Convite não criado · conexão indisponível':'Revise antes de registrar',`${m.error?'<div class="notice amber"><strong>Falha simulada na conexão com Google Agenda</strong>Nenhum convite foi criado. A oportunidade e a tarefa permanecem sem novo agendamento.</div>':''}<dl class="definition"><div class="full"><dt>Título</dt><dd>${esc(m.title)}</dd></div><div><dt>Organizador escolhido</dt><dd>${esc(m.member)}<br>${m.member==='Gustavo Costa'?'gustavo':'saulo'}@example.com</dd></div><div><dt>Convidado</dt><dd>${esc(m.email)}</dd></div><div><dt>Data e hora</dt><dd>${esc(m.date)} · ${esc(m.time)} · Brasília</dd></div><div><dt>Duração</dt><dd>${esc(m.duration)}</dd></div>${m.task?`<div class="full"><dt>Retorno ao contexto</dt><dd>${esc(m.task)} · ${esc(tasks.find(t=>t.id===m.task).title)}</dd></div>`:''}</dl><div class="notice">Registro somente nesta sessão. Não cria evento no Google Agenda, não envia convite nem altera tarefa real do ClickUp.</div><div class="dialog-footer"><button class="btn" id="edit-meeting">Editar dados</button><button class="btn primary" id="confirm-meeting">${m.error?'Simular recuperação e revisar':'Registrar reunião simulada'}</button></div>`);$('#edit-meeting').onclick=()=>{schedule(m.deal,m.task);$('#meeting-title').value=m.title;$('#meeting-member').value=m.member;$('#meeting-lead').value=m.email;$('#meeting-date').value=m.date;$('#meeting-time').value=m.time;$('#meeting-duration').value=m.duration;$('#meeting-scenario').value=m.error?'error':'ready';};$('#confirm-meeting').onclick=()=>{if(m.error){m.error=false;reviewMeeting();return;}const d=deals.find(d=>d.id===m.deal);d.meeting=true;tasks.push({id:'AGENDA-DEMO-'+(tasks.length+1),deal:d.id,title:m.title,owner:m.member,due:m.date,status:'Pendente',source:'Agenda simulada',time:m.time});if(m.task)tasks.find(t=>t.id===m.task).meetingResult=structuredClone(m);activityLog.push({deal:d.id,title:'Reunião registrada · simulação',body:`${m.member} · ${m.date}, ${m.time} · convidado ${m.email}. Nenhum envio.`});invalidateCampaign();render();if(m.task)taskDetail(m.task);else openDeal(d.id);toast('Reunião fictícia registrada. Contexto de origem preservado.');};}
function segments(){return baseSegments()+`<section class="panel panel-body campaign-entry"><div><h2>Preparar campanha · simulação</h2><p class="subtitle">Revise o público, aprove o texto e veja uma prévia de fila. Nenhuma mensagem será enfileirada ou enviada.</p></div><button class="btn primary manager-only" id="prepare-campaign">Revisar público e texto →</button></section>`;}
const exclusionReasons=d=>[d.meeting?'Reunião já marcada':null,d.status!=='Aberta'?'Situação '+d.status:null,!d.consent?'Bloqueio de contato · hipótese':null].filter(Boolean);
const personalize=(text,d)=>text.replaceAll('{contato}',d.contact||'contato').replaceAll('{empresa}',d.company);
function campaignView(step='publico'){if(profile!=='manager')return;const sig=campaignSignature();if(campaign.signature&&campaign.signature!==sig){invalidateCampaign();step='publico';}campaign.signature=sig;const eligible=deals.filter(segmentEligible);if(!campaign.selected)campaign.selected=new Set(eligible.map(d=>d.id));else campaign.selected=new Set([...campaign.selected].filter(id=>eligible.some(d=>d.id===id)));campaign.step=step;const selected=eligible.filter(d=>campaign.selected.has(d.id));const steps=`<ol class="flow-steps"><li class="${step==='publico'?'current':''}">1. Público</li><li class="${step==='texto'?'current':''}">2. Texto</li><li class="${step==='fila'?'current':''}">3. Prévia</li></ol>`;
if(step==='publico'){modal('Campanha · revisar público',`${steps}<p class="muted">Raio X concluído + sem reunião + oportunidade aberta. Bloqueios de contato são hipótese adicional para validar. Seleção e revisão são fictícias.</p><h3 class="section-title">Elegíveis · ${eligible.length}</h3><div class="check-list">${eligible.map(d=>`<label class="checkrow campaign-person"><input type="checkbox" data-campaign-person="${d.id}" ${campaign.selected.has(d.id)?'checked':''}><span><strong>${esc(d.company)}</strong><br>${esc(d.contact)} · ${esc(d.owner)}</span></label>`).join('')||'<p>Ninguém atende ao recorte atual.</p>'}</div><h3 class="section-title">Excluídos do recorte · ${deals.filter(d=>d.rx&&!segmentEligible(d)).length}</h3>${deals.filter(d=>d.rx&&!segmentEligible(d)).map(d=>`<div class="campaign-exclusion"><strong>${esc(d.company)}</strong><p class="muted">${exclusionReasons(d).map(esc).join(' · ')}</p></div>`).join('')}<p class="muted">${deals.filter(d=>!d.rx).length} oportunidades sem Raio X concluído não entram neste segmento.</p><div class="notice amber">Revisão de público, critérios de contato e perfil que pode aprovar são propostas de experiência, a validar com Saulo e Gustavo. Sem conexão com a Meta.</div><label class="checkrow"><input type="checkbox" id="campaign-audience-reviewed" ${campaign.reviewed?'checked':''}><span>Conferi os selecionados e as exclusões desta simulação.</span></label><div class="dialog-footer"><span id="campaign-count" class="muted">${selected.length} selecionados</span><button class="btn primary" id="campaign-next" ${!campaign.reviewed||!selected.length?'disabled':''}>Editar texto →</button></div>`,'wide');all('[data-campaign-person]').forEach(c=>c.onchange=()=>{if(c.checked)campaign.selected.add(c.dataset.campaignPerson);else campaign.selected.delete(c.dataset.campaignPerson);campaign.reviewed=false;campaign.approved=false;campaign.queue=[];campaignView();});$('#campaign-audience-reviewed').onchange=e=>{campaign.reviewed=e.target.checked;$('#campaign-next').disabled=!campaign.reviewed||!campaign.selected.size;};$('#campaign-next').onclick=()=>{if(campaign.reviewed&&campaign.selected.size)campaignView('texto');};}
if(step==='texto'){if(!campaign.reviewed||!selected.length)return campaignView();modal('Campanha · editar e aprovar texto',`${steps}<p class="muted">${selected.length} destinatários fictícios selecionados. Canal WhatsApp é hipótese; não há integração ou envio.</p><label class="field" style="margin-top:18px">Texto da campanha<textarea id="campaign-text" rows="5">${esc(campaign.text)}</textarea></label><p class="subtitle">Marcadores suportados: {contato} e {empresa}. A prévia abaixo usa o primeiro selecionado.</p><section class="campaign-message"><span class="eyebrow">Prévia individual · ${esc(selected[0].company)}</span><p id="campaign-text-preview">${esc(personalize(campaign.text,selected[0]))}</p></section><label class="checkrow"><input type="checkbox" id="campaign-text-approved" ${campaign.approved?'checked':''}><span>Aprovo este texto apenas para visualizar a fila fictícia. Identidade ilustrativa: Gustavo Costa.</span></label><p class="notice amber">Aprovação e conteúdo são hipóteses para validação. Editar o texto invalida a aprovação anterior.</p><div class="dialog-footer"><button class="btn" id="campaign-back">Voltar ao público</button><button class="btn primary" id="campaign-preview" ${!campaign.approved||!campaign.text.trim()?'disabled':''}>Ver prévia da fila →</button></div>`,'wide');$('#campaign-text').oninput=e=>{campaign.text=e.target.value;campaign.approved=false;campaign.queue=[];$('#campaign-text-approved').checked=false;$('#campaign-preview').disabled=true;$('#campaign-text-preview').textContent=personalize(campaign.text,selected[0]);};$('#campaign-text-approved').onchange=e=>{campaign.approved=e.target.checked;$('#campaign-preview').disabled=!campaign.approved||!campaign.text.trim();};$('#campaign-back').onclick=()=>{campaign.approved=false;campaignView();};$('#campaign-preview').onclick=()=>{if(!campaign.approved||!campaign.text.trim())return;campaign.queue=selected.map(d=>({deal:d.id,company:d.company,contact:d.contact,text:personalize(campaign.text,d),state:'Prévia · não enfileirada'}));campaignView('fila');};}
if(step==='fila'){if(!campaign.approved||!campaign.queue.length)return campaignView('texto');modal('Campanha · prévia da fila',`${steps}<div class="notice"><strong>${campaign.queue.length} mensagens fictícias para conferência</strong>Texto aprovado na simulação por Gustavo Costa. Esta lista não é uma fila operacional: nenhum item foi enfileirado, agendado ou enviado.</div>${campaign.queue.map((r,i)=>`<article class="campaign-message"><div class="split"><strong>${i+1}. ${esc(r.company)}</strong>${tag(r.state,'amber')}</div><p class="muted">${esc(r.contact)} · WhatsApp como hipótese</p><p class="campaign-body">${esc(r.text)}</p></article>`).join('')}<div class="dialog-footer"><button class="btn" id="campaign-edit-public">Rever público</button><button class="btn" id="campaign-edit-text">Editar texto e reaprová-lo</button><button class="btn primary" id="campaign-done">Concluir prévia sem envio</button></div>`,'wide');$('#campaign-edit-public').onclick=()=>{campaign.reviewed=false;campaign.approved=false;campaign.queue=[];campaignView();};$('#campaign-edit-text').onclick=()=>{campaign.approved=false;campaign.queue=[];campaignView('texto');};$('#campaign-done').onclick=()=>{close();toast('Prévia concluída. Nenhuma mensagem enfileirada ou enviada.');};}}
const baseBind=bind;
bind=function(){baseBind();if(section==='funis'&&profile==='manager'){const toolbar=$('#content .toolbar');const create=document.createElement('button');create.className='btn teal';create.id='create-opportunity';create.textContent='+ Nova oportunidade';create.onclick=()=>opportunityForm();toolbar.append(create);}$('#prepare-campaign')?.addEventListener('click',()=>campaignView());const guide=document.querySelector('.demo a');if(guide)guide.textContent='Escopo e simulações';};
const originalDesignState=window.designState;
window.designState=()=>({...originalDesignState(),campaign:{step:campaign.step,selected:[...(campaign.selected||[])],reviewed:campaign.reviewed,text:campaign.text,approved:campaign.approved,queue:structuredClone(campaign.queue)},externalWrites:0});

const demoParams=new URLSearchParams(location.search);
if(demoParams.get('demo')==='raiox'){
 rules=[{field:'status',op:'eq',value:'Aberta'},{field:'rx',op:'eq',value:'Sim'},{field:'meeting',op:'eq',value:'Não'}];
 savedDashboards.push({id:'dash-raiox',name:'Raio X · sem reunião',rules:structuredClone(rules),logic:'all',metric:'value',group:'center'});activeDash='dash-raiox';
}
if(demoParams.get('view')==='atrasadas'){section='atividades';taskOwner='Gustavo Costa';taskDue='Atrasadas';}
render();
if(demoParams.get('view')==='ficha')openDeal('d1');
if(demoParams.get('view')==='agenda')schedule('d1');
if(demoParams.get('view')==='filtros')filterDialog(true);
if(demoParams.get('view')==='nova')opportunityForm();
if(demoParams.get('view')==='editar')opportunityForm('d1');
if(demoParams.get('view')==='produto')createProduct('d1');
if(demoParams.get('view')==='tarefa')taskDetail('DEMO-101');
if(demoParams.get('view')==='campanha'){nav('segmentos');campaignView();}

})();
